package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
import vn.smartfarm.iot.nodes.*;import vn.smartfarm.iot.irrigation.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true","smartfarm.control.circuit-route-required=true","smartfarm.irrigation.circuit-demo-enabled=true","smartfarm.irrigation.session-enabled=true"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class ZoneRainGateTest {
 @Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired ZoneRainGate gate;@Autowired NodeInventory nodes;@Autowired TelemetryRouter router;
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired PumpCircuitProof proof;@Autowired CircuitValveControl valves;@Autowired IrrigationCircuits circuits;@Autowired IrrigationSession sessions;@Autowired MockMvc mvc;
 @MockitoBean CommandTransport transport;@MockitoBean CircuitValveTransport valveTransport;
 UUID boot=UUID.fromString("84000000-0000-4000-8000-000000000001"),vboot=UUID.fromString("84000000-0000-4000-8000-000000000002");PumpCircuitRoute route;
 @BeforeEach void setup()throws Exception{
  cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");reset(transport,valveTransport);when(transport.controlConnected()).thenReturn(true);when(valveTransport.circuitValveConnected(anyString())).thenReturn(true);
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('RGSOIL','Soil','AREA001','SOIL',2),('RGWATER','Water','AREA001','WATER',2)");
  for(int i=1;i<=3;i++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('RGSOIL',?,'SOIL_MOISTURE','%')","SOIL"+i);
  jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('RGWATER','LOW','WATER_PRESENT','boolean'),('RGWATER','FLOW','FLOW_RATE','L/min')");
  jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES('RGZONE','Zone','AREA001','RGSOIL','SIMULATOR',30,35)");
  jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES('RGC','Circuit','RGZONE',1,'IRRIGATION76','VALVE76','PUMP01','RGWATER','LOW','FLOW','SIMULATOR')");
  nodes.registerWeather(mapper.readTree("{\"nodeId\":\"RGWEATHER\",\"name\":\"Rain\",\"areaId\":\"AREA001\",\"channels\":[{\"channelId\":\"RAIN\",\"metric\":\"RAIN_DETECTED\",\"unit\":\"boolean\",\"calibrationVersion\":null},{\"channelId\":\"LIGHT\",\"metric\":\"LIGHT_ILLUMINANCE\",\"unit\":\"lux\",\"calibrationVersion\":\"SIM_LUX_V1\"}]}"));
  route=PumpCircuitRoute.from(circuits.find("RGC"));pumpStatus(1,0,"OFF");valveStatus(1,0,"CLOSED");
 }
 @AfterEach void after(){cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");}
 void cleanup(){jdbc.update("DELETE FROM irrigation_session_action WHERE session_id IN(SELECT session_id FROM irrigation_session WHERE circuit_id='RGC')");jdbc.update("DELETE FROM irrigation_session WHERE circuit_id='RGC'");for(String t:List.of("circuit_demo_command","circuit_demo_status","circuit_demo_boot","circuit_demo_gate"))jdbc.update("DELETE FROM "+t+" WHERE valve_id='VALVE76'");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id='RGC'");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id='RGZONE'");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('RGSOIL','RGWATER','RGWEATHER')");jdbc.update("DELETE FROM sensor_area WHERE id='RGAREA'");}
 ZoneRainGate.Request request(int revision,boolean enabled){return new ZoneRainGate.Request(revision,1,"RGWEATHER","RAIN","SIMULATOR",null,enabled);}
 void enable(){gate.save("RGZONE",request(0,true));}
 ObjectNode packet(long seq,Boolean rain,Instant at)throws Exception {var p=(ObjectNode)mapper.readTree(getClass().getResourceAsStream("/weather-firmware-packet.json"));p.put("deviceId","RGWEATHER").put("sequence",seq).put("timestamp",at.toString());var r=(ObjectNode)p.path("readings").get(0);if(rain==null)r.put("quality","SENSOR_FAULT").putNull("value");else r.put("value",rain);return p;}
 void rain(long seq,Boolean value,Instant at)throws Exception {router.store("smartfarm/FARM001/RGWEATHER/telemetry",mapper.writeValueAsBytes(packet(seq,value,at)));}
 void pumpStatus(long seq,long ordinal,String state)throws Exception {var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",boot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("connection","ONLINE").put("reportedState",state).put("safetyLockout",false).put("stateReason",state.equals("ON")?"COMMAND_ON":"COMMAND_OFF");p.putObject("commandFence").put("version",1).put("lastOrdinal",ordinal).put("restartRequired",false);p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault").set("route",mapper.valueToTree(route));pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p));}
 ObjectNode valvePacket(long seq,long ordinal,String state){var c=circuits.find("RGC");var p=mapper.createObjectNode().put("schemaVersion",1).put("controlProfile",CircuitValveControl.PROFILE).put("controllerId",c.controllerId()).put("actuatorId",c.valveId()).put("circuitId",c.circuitId()).put("circuitRevision",1).put("zoneId",c.zoneId()).put("zoneRevision",1).put("bootId",vboot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("dataSource","SIMULATOR").put("feedbackState",state).put("gpioState",state).put("reason",state.equals("OPEN")?"COMMAND_OPEN":"COMMAND_CLOSE").put("demoEnabled",true).put("lastOrdinal",ordinal);p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",state).putNull("fault");return p;}
 void valveStatus(long seq,long ordinal,String state)throws Exception {valves.receive(CircuitValveControl.topic("VALVE76","status"),mapper.writeValueAsBytes(valvePacket(seq,ordinal,state)),false);}
 void open()throws Exception {var c=valves.create("RGC",new CircuitValveControl.Request(UUID.randomUUID(),"OPEN",30,vboot,1,1,Instant.now()));var p=valvePacket(2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");valves.receive(CircuitValveControl.topic("VALVE76","ack"),mapper.writeValueAsBytes(p),false);valveStatus(3,c.ordinal(),"OPEN");}
 PumpCommandFencing.HttpIntent intent(String action){var c=fencing.view().intent();return new PumpCommandFencing.HttpIntent(UUID.randomUUID(),action,action.equals("ON")?5:null,action.equals("OFF")?null:boot,c.revision(),c.asOf(),action.equals("OFF")?null:route);}
 @Test void defaultAndDisabledPolicyPreserveExistingBehaviour(){assertEquals("NOT_CONFIGURED",gate.snapshot("RGZONE").state());assertTrue(gate.snapshot("RGZONE").allowed());gate.save("RGZONE",request(0,false));assertEquals("DISABLED",gate.snapshot("RGZONE").state());assertTrue(gate.snapshot("RGZONE").allowed());}
 @Test void enablingWithoutSampleBlocksAndFreshDryPermitsNewStart()throws Exception {enable();assertEquals("MISSING",gate.snapshot("RGZONE").state());assertFalse(gate.snapshot("RGZONE").allowed());assertFalse(sessions.snapshot("RGC").canStart());rain(1,false,Instant.now());assertEquals("DRY",gate.snapshot("RGZONE").state());assertTrue(sessions.snapshot("RGC").canStart());}
 @Test void rainFaultOldSourceSkewAndCalibrationNeverBecomeDry()throws Exception {
  enable();rain(1,true,Instant.now());assertEquals("RAIN",gate.snapshot("RGZONE").state());rain(2,null,Instant.now());assertEquals("SENSOR_FAULT",gate.snapshot("RGZONE").state());
  jdbc.update("UPDATE node_sample SET observed_at=CURRENT_TIMESTAMP-INTERVAL '31 seconds' WHERE node_id='RGWEATHER'");assertEquals("STALE",gate.snapshot("RGZONE").state());
  jdbc.update("UPDATE node_sample SET observed_at=CURRENT_TIMESTAMP+INTERVAL '3 seconds' WHERE node_id='RGWEATHER'");assertEquals("CLOCK_SKEW",gate.snapshot("RGZONE").state());assertFalse(gate.snapshot("RGZONE").allowed());
 }
 @Test void sourceMismatchAndCalibrationMismatchBlock()throws Exception {enable();var p=packet(1,false,Instant.now()).put("dataSource","PHYSICAL");router.store("smartfarm/FARM001/RGWEATHER/telemetry",mapper.writeValueAsBytes(p));assertEquals("SOURCE_MISMATCH",gate.snapshot("RGZONE").state());jdbc.update("UPDATE node_sample SET data_source='SIMULATOR' WHERE node_id='RGWEATHER'");jdbc.update("UPDATE channel_sample SET calibration_version='OTHER' WHERE node_id='RGWEATHER' AND channel_id='RAIN'");assertEquals("CALIBRATION_MISMATCH",gate.snapshot("RGZONE").state());}
 @Test void duplicateOldAndLightOnlyReportsCannotRefreshRain()throws Exception {enable();rain(1,false,Instant.now().minusSeconds(31));var light=packet(2,false,Instant.now());light.withArray("readings").remove(0);router.store("smartfarm/FARM001/RGWEATHER/telemetry",mapper.writeValueAsBytes(light));assertEquals("STALE",gate.snapshot("RGZONE").state());var duplicate=packet(1,false,Instant.now());assertFalse(router.store("smartfarm/FARM001/RGWEATHER/telemetry",mapper.writeValueAsBytes(duplicate)));assertEquals("STALE",gate.snapshot("RGZONE").state());}
 @Test void expirationUsesBothSourceAndReceiptAtExactThirtySecondBoundary()throws Exception {enable();Instant at=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);rain(1,false,at);assertEquals("DRY",ZoneRainGate.inspect(jdbc,"RGZONE",at.plusSeconds(29)).state());assertEquals("STALE",ZoneRainGate.inspect(jdbc,"RGZONE",at.plusSeconds(30)).state());jdbc.update("UPDATE node_sample SET received_at=observed_at-INTERVAL '31 seconds' WHERE node_id='RGWEATHER'");assertEquals("STALE",ZoneRainGate.inspect(jdbc,"RGZONE",at).state());}
 @Test void policyRevisionAndZoneRevisionMustMatch(){enable();assertThrows(Exception.class,()->gate.save("RGZONE",request(0,false)));jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='RGZONE'");assertEquals("CONFIG_CHANGED",gate.snapshot("RGZONE").state());assertThrows(Exception.class,()->gate.save("RGZONE",request(1,false)));}
 @Test void missingOrMovedNodeCannotBeSilentlyReplaced()throws Exception {enable();rain(1,false,Instant.now());jdbc.update("DELETE FROM iot_node WHERE node_id='RGWEATHER'");assertEquals("CHANNEL_UNAVAILABLE",gate.snapshot("RGZONE").state());assertFalse(gate.snapshot("RGZONE").allowed());assertEquals(false,gate.save("RGZONE",request(1,false)).enabled());}
 @Test void wrongChannelTypeAreaSourceAndProfileCannotBeEnabled(){for(var q:List.of(new ZoneRainGate.Request(0,1,"RGWEATHER","LIGHT","SIMULATOR","SIM_LUX_V1",true),new ZoneRainGate.Request(0,1,"RGWATER","LOW","SIMULATOR",null,true),new ZoneRainGate.Request(0,1,"RGWEATHER","RAIN","PHYSICAL",null,true)))assertThrows(Exception.class,()->gate.save("RGZONE",q));var offProfile=new ZoneRainGate(jdbc,false,false,false,false);assertThrows(Exception.class,()->offProfile.save("RGZONE",request(0,true)));assertFalse(offProfile.save("RGZONE",request(0,false)).enabled());}
 @Test void invalidPolicyAndUnknownZoneDoNotWrite()throws Exception {mvc.perform(put("/api/v1/irrigation-zones/RGZONE/weather").contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/irrigation-zones/NOZONE/weather")).andExpect(status().isNotFound());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM zone_rain_gate WHERE zone_id='RGZONE'",Integer.class));}
 @Test void directOnIsRejectedDespiteSuccessfulOldPreviewWhenRainArrives()throws Exception {enable();rain(1,false,Instant.now());open();assertTrue(proof.snapshot("RGC").readyToStart());var q=intent("ON");rain(2,true,Instant.now());assertFalse(proof.snapshot("RGC").readyToStart());assertThrows(Exception.class,()->fencing.createHttp(q,()->{}));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM pump_command",Integer.class));verify(transport,never()).publishCommand(any());}
 @Test void dryAdmissionStoresExactPolicyAndSourceSampleThenDuplicateDoesNotReplay()throws Exception {enable();rain(1,false,Instant.now());open();var q=intent("ON");var c=fencing.createHttp(q,()->{});String json=jdbc.queryForObject("SELECT weather_gate::text FROM pump_command WHERE command_id=?",String.class,c.command().commandId());var evidence=mapper.readTree(json);assertEquals("DRY",evidence.path("state").asText());assertEquals(1,evidence.path("policy").path("revision").asInt());assertEquals(false,evidence.path("sample").path("value").asBoolean());rain(2,true,Instant.now());fencing.createHttp(q,()->{});assertEquals(json,jdbc.queryForObject("SELECT weather_gate::text FROM pump_command WHERE command_id=?",String.class,q.requestId()));verify(transport,times(1)).publishCommand(any());}
 @Test void emergencyOffRemainsAvailableUnderRainOrMissingData()throws Exception {enable();rain(1,true,Instant.now());fencing.createHttp(intent("OFF"),()->{});verify(transport,times(1)).publishCommand(any());assertNull(jdbc.queryForObject("SELECT weather_gate FROM pump_command",Object.class));}
 @Test void activeSessionCannotDisableItsWeatherPolicy()throws Exception {enable();rain(1,false,Instant.now());var v=sessions.snapshot("RGC");sessions.start("RGC",new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,5,v.asOf()));assertThrows(Exception.class,()->gate.save("RGZONE",request(1,false)));}
 @Test void rainBetweenSessionCreationAndOpenBlocksOpeningWithoutDispatch()throws Exception {enable();rain(1,false,Instant.now());var v=sessions.snapshot("RGC");var r=sessions.start("RGC",new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,5,v.asOf()));rain(2,true,Instant.now());assertFalse(sessions.snapshot("RGC").canOpen());assertThrows(Exception.class,()->sessions.act("RGC",r.sessionId(),new IrrigationSession.Action(UUID.randomUUID(),"OPEN",r.revision(),Instant.now())));verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void genericAndLegacyOnCannotBypassAnEnabledPolicy()throws Exception {enable();assertThrows(Exception.class,()->ZoneRainGate.requireOn(jdbc,null));assertThrows(Exception.class,()->pump.create(new PumpService.Request("ON",5)));var unfenced=mock(PumpCommandFencing.class);when(unfenced.view()).thenReturn(new PumpCommandFencing.View(false,false,true,false,null,null,null,false,null));var beans=new org.springframework.beans.factory.support.StaticListableBeanFactory(Map.of("testTransport",transport));var legacy=new PumpService(jdbc,mapper,beans.getBeanProvider(CommandTransport.class),true,unfenced);var error=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->legacy.create(new PumpService.Request("ON",5)));assertEquals("WEATHER_ROUTE_REQUIRED",error.getReason());verify(transport,never()).publishCommand(any());}
 @Test void savingPolicyNeverDispatchesAndReadOnlyViewDoesNotRefreshSample()throws Exception {enable();rain(1,false,Instant.now());String before=jdbc.queryForObject("SELECT row_to_json(s)::text FROM node_sample s WHERE node_id='RGWEATHER'",String.class);mvc.perform(get("/api/v1/irrigation-zones/RGZONE/weather")).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("DRY"));assertEquals(before,jdbc.queryForObject("SELECT row_to_json(s)::text FROM node_sample s WHERE node_id='RGWEATHER'",String.class));verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void declaredWeatherMustStayInTheSameArea(){jdbc.update("INSERT INTO sensor_area(id,name) VALUES('RGAREA','Other') ON CONFLICT DO NOTHING");jdbc.update("UPDATE iot_node SET area_id='RGAREA' WHERE node_id='RGWEATHER'");assertThrows(Exception.class,()->gate.save("RGZONE",request(0,true)));}
 @Test void rainAfterAdmissionDoesNotInventAnAutomaticOff()throws Exception {enable();rain(1,false,Instant.now());open();fencing.createHttp(intent("ON"),()->{});rain(2,true,Instant.now());assertEquals("RAIN",gate.snapshot("RGZONE").state());assertEquals(List.of("ON"),jdbc.queryForList("SELECT action FROM pump_command",String.class));verify(transport,times(1)).publishCommand(any());}

}
